  for (let i = lines.length - 1; i >= 0; i -= 1) {
    const match = lines[i].match(DEFINITION);
    if (match) return { index: i, prefix: match[1], parsed: parseEnvValue(match[2]) };
  }
  return null;
};

const formatEnvValue = (key) => (/^[^\s#'"\\]+$/.test(key) ? key : JSON.stringify(key));

export const getLocalApiKey = (cwd = process.cwd()) => {
