import fs from 'fs';
import os from 'os';
import path from 'path';
import { describe, expect, it, beforeEach, afterEach } from 'vitest';

import {
  getGlobalApiKey,
  getLocalApiKey,
  hasGlobalApiKey,
  hasLocalApiKey,
  setGlobalApiKey,
  setLocalApiKey
} from './key-store.js';
import { resolveGlobalConfigPath, resolveLocalEnvPath } from './paths.js';

describe('config key store', () => {
  let tmpCwd;
  let tmpHome;

  beforeEach(() => {
    tmpCwd = fs.mkdtempSync(path.join(os.tmpdir(), 'frai-cwd-'));
    tmpHome = fs.mkdtempSync(path.join(os.tmpdir(), 'frai-home-'));
  });

  afterEach(() => {
    fs.rmSync(tmpCwd, { recursive: true, force: true });
    fs.rmSync(tmpHome, { recursive: true, force: true });
  });

  it('handles local env api key lifecycle', () => {
    expect(hasLocalApiKey(tmpCwd)).toBe(false);
    expect(getLocalApiKey(tmpCwd)).toBeNull();

    setLocalApiKey('test-key', tmpCwd);

    expect(hasLocalApiKey(tmpCwd)).toBe(true);
    expect(getLocalApiKey(tmpCwd)).toBe('test-key');

    const envPath = resolveLocalEnvPath(tmpCwd);
    const content = fs.readFileSync(envPath, 'utf8');
    expect(content).toContain('OPENAI_API_KEY=test-key');
  });

  it('handles global config api key lifecycle', () => {
    expect(hasGlobalApiKey(tmpHome)).toBe(false);
    expect(getGlobalApiKey(tmpHome)).toBeNull();

    setGlobalApiKey('global-key', tmpHome);

    expect(hasGlobalApiKey(tmpHome)).toBe(true);
    expect(getGlobalApiKey(tmpHome)).toBe('global-key');

    const configPath = resolveGlobalConfigPath(tmpHome);
    const content = fs.readFileSync(configPath, 'utf8');
    expect(JSON.parse(content).OPENAI_API_KEY).toBe('global-key');
  });
});

#!/usr/bin/env node
import fs from 'fs';
import path from 'path';
import process from 'process';
import { execSync } from 'child_process';
import { createRequire } from 'module';
import { Command } from 'commander';
import inquirer from 'inquirer';
import { Config, Documents, Eval, Finetune, Providers, Questionnaire, Rag, Scanners } from 'frai-core';
const require = createRequire(import.meta.url);
const pkg = require('../package.json');
const DOC_FILENAMES = ['checklist.md', 'model_card.md', 'risk_file.md'];
const LOCAL_ENV_DISPLAY = '.env';
const GLOBAL_CONFIG_DISPLAY = '~/.config/frai/config';
const log = {
    info(message, meta) {
        console.log(formatLog('info', message, meta));
    },
    success(message, meta) {
        console.log(formatLog('success', message, meta));
    },
    warn(message, meta) {
        console.warn(formatLog('warn', message, meta));
    },
    error(message, meta) {
        console.error(formatLog('error', message, meta));
    }
};
function formatLog(level, message, meta = undefined) {
    const timestamp = new Date().toISOString();
    if (!meta || Object.keys(meta).length === 0) {
        return `[${timestamp}] ${level.toUpperCase()} ${message}`;
    }
    let serializedMeta = '';
    try {
        serializedMeta = JSON.stringify(meta);
    }
    catch (error) {
        serializedMeta = String(meta);
    }
    return `[${timestamp}] ${level.toUpperCase()} ${message} ${serializedMeta}`;
}
function listDocs() {
    const cwd = process.cwd();
    const items = DOC_FILENAMES.filter((file) => fs.existsSync(path.join(cwd, file)));
    if (!items.length) {
        log.info('No documentation files detected in current directory.', { cwd });
        return;
    }
    log.info('Documentation files found:', { files: items });
    items.forEach((file) => console.log(`  - ${file}`));
}
function cleanDocs() {
    const cwd = process.cwd();
    let removed = 0;
    for (const file of DOC_FILENAMES) {
        const target = path.join(cwd, file);
        if (fs.existsSync(target)) {
            fs.unlinkSync(target);
            removed += 1;
            log.info(`Removed ${file}`);
        }
    }
    if (!removed) {
        log.info('No documentation files to remove.');
    }
    else {
        log.success('Documentation directory cleaned.', { removed });
    }
}
function exportDocsAsPdf() {
    const existing = DOC_FILENAMES.filter((file) => fs.existsSync(file));
    if (!existing.length) {
        log.warn('No documentation files to export.');
        return;
    }
    try {
        execSync(`npx markdown-pdf ${existing.join(' ')}`, { stdio: 'inherit' });
        log.success('PDF export complete.');
    }
    catch (error) {
        log.error('Failed to export documentation as PDF.', {
            error: error instanceof Error ? error.message : String(error)
        });
    }
}
function showConfigStatus() {
    const local = {
        exists: Config.hasLocalApiKey(),
        value: Config.getLocalApiKey()
    };
    const global = {
        exists: Config.hasGlobalApiKey(),
        value: Config.getGlobalApiKey()
    };
    const status = {
        local: {
            configured: local.exists,
            location: LOCAL_ENV_DISPLAY
        },
        global: {
            configured: global.exists,
            location: GLOBAL_CONFIG_DISPLAY
        }
    };
    log.info('API key configuration status', status);
    if (local.exists) {
        log.info('Local API key detected (masked).');
    }
    if (global.exists) {
        log.info('Global API key detected (masked).');
